(()=>{'use strict';const $=id=>document.getElementById(id);const btn=$('retry');async function load(){btn.disabled=true;$('status').textContent='Retrieving source headlines…';$('summary').textContent='Loading today’s briefing…';$('headlines').replaceChildren();try{const res=await fetch('/api/news/daily',{headers:{'Accept':'application/json'}});if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();$('date').textContent=data.date_utc+' UTC';$('summary').textContent=data.summary||('AI summary unavailable: '+(data.summary_note||'Please retry later.'));$('status').textContent=data.headlines.length?('LATEST BRIEFING · '+data.headlines.length+' SOURCED HEADLINES'):'No recent headlines could be retrieved. Please try again later.';$('count').textContent=data.headlines.length+' HEADLINES · LAST 48 HOURS';for(const [i,item] of data.headlines.entries()){const li=document.createElement('li'),wrap=document.createElement('div'),link=document.createElement('a'),meta=document.createElement('div');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=item.title;meta.className='meta';meta.textContent=item.channel+' · '+new Date(item.published_utc).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC · SOURCE '+(i+1);wrap.append(link,meta);li.append(wrap);$('headlines').append(li);}if(!data.headlines.length){const li=document.createElement('li');li.textContent='No source coverage available at this time.';$('headlines').append(li);}}catch(e){$('status').textContent='Unable to load the briefing right now.';$('summary').textContent='The news feed is unavailable. Check your connection and try again.';}finally{btn.disabled=false}}btn.addEventListener('click',load);load()})();